(()=>{'use strict';const S=[...document.querySelectorAll('.session')],B=document.querySelector('#progressBar'),K='festividades-v2',es=document.documentElement.lang==='es',w=(m,e)=>console.warn('[festividades] '+m,e||''),get=()=>{try{return new Set(JSON.parse(localStorage.getItem(K)||'[]'))}catch(e){w('storage',e);return new Set}},D=get(),save=()=>{try{localStorage.setItem(K,JSON.stringify([...D]))}catch(e){w('storage',e)}},draw=()=>{S.forEach((x,i)=>{let n=i+1,d=D.has(n),b=x.querySelector('.btn-complete');x.classList.toggle('session-completed',d);if(b)b.disabled=d,b.dataset.item=n,b.setAttribute('aria-pressed',d),b.textContent=d?'✅ '+(es?'Festividad ':'Fête ')+n+(es?' completada':' terminée'):b.textContent});let p=S.length?Math.round(100*D.size/S.length):0;if(B)B.style.width=p+'%',B.textContent=p+'%',B.setAttribute('aria-valuenow',p)};document.addEventListener('click',e=>{let b=e.target.closest('.btn-complete');if(!b)return;D.add(+b.dataset.item);save();draw()});document.addEventListener('error',e=>{if(e.target instanceof HTMLImageElement)e.target.hidden=true},true);addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));draw();if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./festividades-sw.js').catch(e=>w('cache',e)),{once:true})})();